I want to replicate the progress I made with my Time Clock App and save it before making changes for deployment.  Build me a demo. Act as a web app consultant and give me suggestions.

<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Timesheet App</title>
    <!-- Tailwind CSS for styling -->
    <script src="https://cdn.tailwindcss.com"></script>
    <!-- Google Fonts: Inter -->
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
    <style>
        /* Use the Inter font family */
        body {
            font-family: 'Inter', sans-serif;
        }
        /* Custom styles for disabled buttons */
        .btn-disabled {
            cursor: not-allowed;
            opacity: 0.5;
        }
        /* Hide elements by default */
        .hidden {
            display: none;
        }
        /* Spinner Animation */
        @keyframes spin {
            to { transform: rotate(360deg); }
        }
        .spinner {
            animation: spin 1s linear infinite;
        }
    </style>
</head>
<body class="bg-gray-100 flex items-center justify-center min-h-screen py-12">

    <!-- Login View -->
    <div id="loginView" class="w-full max-w-md mx-auto bg-white rounded-2xl shadow-lg p-8 space-y-6">
        <div class="text-center">
            <!-- Logo: Changed h-64 to h-32 to make it half the size -->
            <img src="https://i.imgur.com/52HoFpA.png" alt="Company Logo" class="mx-auto h-32 w-auto mb-4">
            <h1 class="text-3xl font-bold text-gray-800 mb-2">Timesheet App</h1>
            <p class="text-gray-500">Please enter your email to continue.</p>
        </div>
        <form id="loginForm">
            <div>
                <label for="email" class="block text-sm font-medium text-gray-700">Email Address</label>
                <input type="email" id="email" name="email" required class="mt-1 w-full p-3 bg-gray-50 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition" placeholder="you@example.com">
            </div>
            <p id="loginError" class="text-red-500 text-sm mt-2 hidden">Invalid email address. Please try again.</p>
            <button type="submit" class="w-full mt-6 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 px-4 rounded-lg transition duration-300 ease-in-out transform hover:scale-105">
                Login
            </button>
        </form>
    </div>

    <!-- App View -->
    <div id="appView" class="w-full max-w-2xl mx-auto bg-white rounded-2xl shadow-lg p-4 space-y-4 hidden relative">
        <div class="flex flex-col items-center">
             <!-- Logo: Added mb-6 for whitespace between logo and text -->
             <img src="https://i.imgur.com/52HoFpA.png" alt="Company Logo" class="h-32 w-auto mb-6">
            <div class="text-center">
                <h1 class="text-3xl font-bold text-gray-800">Time Clock</h1>
                <p id="welcomeMessage" class="text-gray-500">Welcome!</p>
            </div>
        </div>

        <!-- Status & Message Display -->
        <div class="bg-gray-50 rounded-lg p-4 text-center">
            <p id="geoStatus" class="text-sm text-red-500 h-5 mb-1"></p>
            <p class="text-sm font-medium text-gray-500">Current Status</p>
            <p id="status" class="text-2xl font-bold text-indigo-600">Loading...</p>
        </div>

        <!-- Action Buttons -->
        <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
            <button id="clockInBtn" class="w-full bg-gray-600 hover:bg-gray-700 text-white font-bold py-3 px-4 rounded-lg transition duration-300 ease-in-out transform hover:scale-105 flex justify-center items-center gap-2">
                Clock In
            </button>
            <button id="clockOutBtn" class="w-full bg-gray-600 hover:bg-gray-700 text-white font-bold py-3 px-4 rounded-lg transition duration-300 ease-in-out transform hover:scale-105 flex justify-center items-center gap-2">
                Clock Out
            </button>
        </div>

        <!-- Procedure Tracker -->
        <div id="procedureTracker" class="hidden">
            <h3 class="text-lg font-semibold text-gray-700 border-b pb-2 mb-4">Track Procedures</h3>
            <div class="space-y-4"></div>
        </div>

        <!-- Current Session Log -->
        <div id="timeLog" class="space-y-2"></div>

        <!-- History Section -->
        <div>
            <h2 class="text-xl font-semibold text-gray-700 mt-6 border-b pb-2 mb-4">Work History</h2>
            <div id="historyLog" class="space-y-3 max-h-60 overflow-y-auto pr-2"></div>
        </div>
    </div>

    <!-- Confirmation Modal -->
    <div id="confirmationModal" class="fixed inset-0 bg-gray-600 bg-opacity-50 overflow-y-auto h-full w-full hidden flex items-center justify-center z-50">
        <div class="relative p-5 border w-96 shadow-lg rounded-md bg-white">
            <div class="mt-3 text-center">
                <div class="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-indigo-100 mb-4">
                    <svg class="h-6 w-6 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/>
                    </svg>
                </div>
                <h3 class="text-lg leading-6 font-medium text-gray-900">Confirm Procedures & Clock Out</h3>
                <div class="mt-2 px-2 py-3">
                    <p class="text-sm text-gray-500 mb-3">
                        Please verify the procedures recorded for this session:
                    </p>
                    <div id="confirmationProceduresList" class="bg-gray-50 rounded-lg p-3 mb-4 text-left text-sm text-gray-700 max-h-40 overflow-y-auto border border-gray-100">
                        <!-- Populated by JS -->
                    </div>
                    <p class="text-sm text-gray-500">
                        Ready to end your shift?
                    </p>
                </div>
                <div class="flex justify-center gap-4 mt-4">
                    <button id="cancelClockOut" class="px-4 py-2 bg-gray-200 text-gray-800 text-base font-medium rounded-md shadow-sm hover:bg-gray-300 focus:outline-none focus:ring-2 focus:ring-gray-300">
                        Go Back
                    </button>
                    <button id="confirmClockOut" class="px-4 py-2 bg-indigo-600 text-white text-base font-medium rounded-md shadow-sm hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-indigo-500">
                        Confirm & Clock Out
                    </button>
                </div>
            </div>
        </div>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            // --- CONFIGURATION ---
            // PASTE YOUR GOOGLE APPS SCRIPT WEB APP URL HERE:
            const GOOGLE_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbwa6_SJQ1IObCEJrw3D0DDvNP8mzUNeWmyl0v9c05RmPAV1TTKKwrSeAeulssaJGBar/exec';

            // --- DATA ---
            const employees = {
                'ikdilley@gmail.com': { name: 'Isaac Dilley', rate: 50 },
                'btdilley@gmail.com': { name: 'Brian Dilley', rate: 100 },
                'dilleyog@gmail.com': { name: 'Oliva Dilley', rate: 49 }
            };
            const procedures = {
                'Glutithione': { name: 'Glutithione', value: 20 },
                'IV': { name: 'IV', value: 50 },
                'Laser': { name: 'Laser', value: 15 }
            };
            const APP_STORAGE_KEY = 'employeeTimeClockData';
            const SESSION_KEY = 'loggedInUserEmail';

            // --- DOM Elements ---
            const loginView = document.getElementById('loginView');
            const appView = document.getElementById('appView');
            const loginForm = document.getElementById('loginForm');
            const emailInput = document.getElementById('email');
            const loginError = document.getElementById('loginError');
            const welcomeMessage = document.getElementById('welcomeMessage');
            const clockInBtn = document.getElementById('clockInBtn');
            const clockOutBtn = document.getElementById('clockOutBtn');
            const statusDisplay = document.getElementById('status');
            const geoStatus = document.getElementById('geoStatus');
            const timeLogDiv = document.getElementById('timeLog');
            const historyLogDiv = document.getElementById('historyLog');
            const procedureTracker = document.getElementById('procedureTracker');

            // Modal Elements
            const confirmationModal = document.getElementById('confirmationModal');
            const cancelClockOutBtn = document.getElementById('cancelClockOut');
            const confirmClockOutBtn = document.getElementById('confirmClockOut');

            // --- Helper Functions ---
            const spinnerSvg = `<svg class="spinner -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>`;

            function getAppData() {
                const data = JSON.parse(localStorage.getItem(APP_STORAGE_KEY)) || {};
                Object.keys(employees).forEach(email => {
                    if (!data[email]) {
                        data[email] = { currentClockIn: null, history: [] };
                    }
                });
                return data;
            }

            function saveAppData(data) {
                localStorage.setItem(APP_STORAGE_KEY, JSON.stringify(data));
            }

            function formatTime(dateStr) {
                if (!dateStr) return '';
                return new Date(dateStr).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true });
            }

            function formatDate(dateStr) {
                 if (!dateStr) return '';
                 return new Date(dateStr).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
            }

            function formatDuration(ms) {
                if (ms < 0) ms = 0;
                let s = Math.floor(ms / 1000), m = Math.floor(s / 60), h = Math.floor(m / 60);
                return `${h}h ${m % 60}m ${s % 60}s`;
            }

            function getGeoLocation() {
                return new Promise((resolve) => {
                    if (window.location.protocol !== 'https:') {
                        geoStatus.textContent = 'Location requires a secure (https) connection.';
                        resolve(null);
                        return;
                    }
                    if (!navigator.geolocation) {
                        geoStatus.textContent = 'Geolocation is not supported by your browser.';
                        resolve(null);
                        return;
                    }
                    geoStatus.textContent = '';
                    navigator.geolocation.getCurrentPosition(
                        (position) => {
                            resolve({ lat: position.coords.latitude, lon: position.coords.longitude });
                        },
                        () => {
                            geoStatus.textContent = 'Location access denied.';
                            resolve(null);
                        }
                    );
                });
            }

            // --- Core Logic & UI Rendering ---

            function populateProcedureTracker() {
                const container = procedureTracker.querySelector('.space-y-4');
                container.innerHTML = '';
                Object.keys(procedures).forEach(procKey => {
                    const procId = procKey.toLowerCase();
                    const item = document.createElement('div');
                    item.className = 'flex justify-between items-center bg-gray-50 p-3 rounded-lg';
                    item.innerHTML = `
                        <p class="font-medium text-gray-700">${procedures[procKey].name}</p>
                        <div class="flex items-center gap-3">
                            <button data-action="decrement" data-target="${procId}" class="w-8 h-8 bg-gray-200 text-gray-700 font-bold rounded-full hover:bg-gray-300 transition">-</button>
                            <input type="number" id="${procId}-count" value="0" readonly class="w-16 text-center font-semibold bg-white border border-gray-300 rounded-md">
                            <button data-action="increment" data-target="${procId}" class="w-8 h-8 bg-gray-200 text-gray-700 font-bold rounded-full hover:bg-gray-300 transition">+</button>
                        </div>
                    `;
                    container.appendChild(item);
                });
            }

            function renderHistory(history) {
                historyLogDiv.innerHTML = '';
                if (history.length === 0) {
                    historyLogDiv.innerHTML = '<p class="text-gray-500 text-center">No history to display.</p>';
                    return;
                }
                [...history].sort((a, b) => new Date(b.clockOut) - new Date(a.clockOut)).forEach(session => {
                    const sessionDiv = document.createElement('div');
                    sessionDiv.className = 'bg-white border border-gray-200 p-4 rounded-lg shadow-sm';
                    const duration = new Date(session.clockOut) - new Date(session.clockIn);

                    const locIn = session.locations?.clockIn ? `<a href="https://www.google.com/maps?q=${session.locations.clockIn.lat},${session.locations.clockIn.lon}" target="_blank" class="text-indigo-600 hover:underline">View Map</a>` : '<span class="text-gray-400">N/A</span>';
                    const locOut = session.locations?.clockOut ? `<a href="https://www.google.com/maps?q=${session.locations.clockOut.lat},${session.locations.clockOut.lon}" target="_blank" class="text-indigo-600 hover:underline">View Map</a>` : '<span class="text-gray-400">N/A</span>';

                    let proceduresHtml = '';
                    if (session.procedures && Object.keys(session.procedures).length > 0) {
                        proceduresHtml = Object.entries(session.procedures)
                            .map(([key, value]) => `<li class="flex justify-between text-xs"><span class="text-gray-600">${key}:</span> <span class="font-semibold">${value}</span></li>`)
                            .join('');
                        proceduresHtml = `<h4 class="text-sm font-semibold mt-3 mb-1 pt-2 border-t">Procedures</h4><ul class="space-y-1">${proceduresHtml}</ul>`;
                    }

                    sessionDiv.innerHTML = `
                        <div class="flex justify-between items-center mb-2">
                            <p class="font-bold text-gray-800">${formatDate(session.clockIn)}</p>
                            <p class="px-3 py-1 bg-indigo-100 text-indigo-700 text-xs font-semibold rounded-full">${formatDuration(duration)}</p>
                        </div>
                        <div class="text-sm text-gray-600 grid grid-cols-2 gap-x-4 gap-y-1">
                            <p><span class="font-semibold">In:</span> ${formatTime(session.clockIn)}</p>
                            <p>${locIn}</p>
                            <p><span class="font-semibold">Out:</span> ${formatTime(session.clockOut)}</p>
                            <p>${locOut}</p>
                        </div>
                        ${proceduresHtml}
                    `;
                    historyLogDiv.appendChild(sessionDiv);
                });
            }

            function updateUI() {
                const loggedInEmail = sessionStorage.getItem(SESSION_KEY);
                if (!loggedInEmail) return;

                const appData = getAppData();
                const employeeData = appData[loggedInEmail];
                const employee = employees[loggedInEmail];

                welcomeMessage.textContent = `Welcome, ${employee.name}!`;

                if (employeeData.currentClockIn) {
                    statusDisplay.textContent = 'Clocked In';
                    clockInBtn.disabled = true;
                    clockOutBtn.disabled = false;
                    procedureTracker.classList.remove('hidden');
                } else {
                    statusDisplay.textContent = 'Clocked Out';
                    clockInBtn.disabled = false;
                    clockOutBtn.disabled = true;
                    procedureTracker.classList.add('hidden');
                }
                renderHistory(employeeData.history);
            }

            function checkLoginState() {
                const loggedInEmail = sessionStorage.getItem(SESSION_KEY);
                if (loggedInEmail && employees[loggedInEmail]) {
                    loginView.classList.add('hidden');
                    appView.classList.remove('hidden');
                    updateUI();
                } else {
                    loginView.classList.remove('hidden');
                    appView.classList.add('hidden');
                }
            }

            // --- Event Handlers ---
            loginForm.addEventListener('submit', (e) => {
                e.preventDefault();
                const email = emailInput.value.trim();
                if (employees[email]) {
                    sessionStorage.setItem(SESSION_KEY, email);
                    loginError.classList.add('hidden');
                    checkLoginState();
                } else {
                    loginError.classList.remove('hidden');
                }
            });

            clockInBtn.addEventListener('click', async () => {
                // UI Updates for Loading
                clockInBtn.disabled = true;
                const originalText = clockInBtn.innerHTML;
                clockInBtn.innerHTML = `${spinnerSvg} Getting Location...`;

                const location = await getGeoLocation();

                Object.keys(procedures).forEach(procKey => {
                    document.getElementById(`${procKey.toLowerCase()}-count`).value = 0;
                });

                const loggedInEmail = sessionStorage.getItem(SESSION_KEY);
                const appData = getAppData();
                appData[loggedInEmail].currentClockIn = {
                    time: new Date().toISOString(),
                    location: location
                };
                saveAppData(appData);

                // Reset UI
                clockInBtn.innerHTML = originalText;
                updateUI();
            });

            // Modal Handlers
            clockOutBtn.addEventListener('click', () => {
                // Populate the confirmation list
                const listContainer = document.getElementById('confirmationProceduresList');
                listContainer.innerHTML = '';

                let hasProcedures = false;
                Object.keys(procedures).forEach(procKey => {
                    const procId = procKey.toLowerCase();
                    const countInput = document.getElementById(`${procId}-count`);
                    const count = countInput ? (parseInt(countInput.value, 10) || 0) : 0;

                    if (count > 0) {
                        hasProcedures = true;
                        const item = document.createElement('div');
                        item.className = 'flex justify-between items-center border-b border-gray-200 last:border-0 py-2';
                        item.innerHTML = `<span class="font-medium">${procedures[procKey].name}</span><span class="font-bold bg-indigo-100 text-indigo-800 px-2 py-0.5 rounded-full text-xs">${count}</span>`;
                        listContainer.appendChild(item);
                    }
                });

                if (!hasProcedures) {
                    listContainer.innerHTML = '<p class="text-gray-400 italic text-center py-2">No procedures recorded for this session.</p>';
                }

                confirmationModal.classList.remove('hidden');
            });

            cancelClockOutBtn.addEventListener('click', () => {
                confirmationModal.classList.add('hidden');
            });

            confirmClockOutBtn.addEventListener('click', async () => {
                // Close modal and start processing
                confirmationModal.classList.add('hidden');

                // UI Updates for Loading on the main button
                clockOutBtn.disabled = true;
                const originalText = clockOutBtn.innerHTML;
                clockOutBtn.innerHTML = `${spinnerSvg} Saving...`;

                const location = await getGeoLocation();

                const loggedInEmail = sessionStorage.getItem(SESSION_KEY);
                const appData = getAppData();
                const employeeData = appData[loggedInEmail];

                if (employeeData.currentClockIn) {
                    const clockOutTime = new Date();
                    const clockInTime = new Date(employeeData.currentClockIn.time);
                    const totalMillis = clockOutTime - clockInTime;
                    const totalHours = totalMillis / (1000 * 60 * 60);

                    const procedureData = {};
                    let commissionPay = 0;
                    Object.keys(procedures).forEach(procKey => {
                        const count = parseInt(document.getElementById(`${procKey.toLowerCase()}-count`).value, 10);
                        if (count > 0) {
                            procedureData[procKey] = count;
                            commissionPay += procedures[procKey].value * count;
                        }
                    });

                    const hourlyPay = totalHours * employees[loggedInEmail].rate;
                    const totalPay = hourlyPay + commissionPay;

                    const sessionData = { 
                        clockIn: employeeData.currentClockIn.time, 
                        clockOut: clockOutTime.toISOString(),
                        procedures: procedureData,
                        locations: {
                            clockIn: employeeData.currentClockIn.location,
                            clockOut: location
                        }
                    };

                    employeeData.history.push(sessionData);
                    employeeData.currentClockIn = null;
                    saveAppData(appData);

                    // --- Send data to Google Sheets ---
                    const payload = {
                        employeeName: employees[loggedInEmail].name,
                        clockIn: formatTime(sessionData.clockIn),
                        clockOut: formatTime(sessionData.clockOut),
                        totalHours: totalHours.toFixed(2),
                        locationIn: sessionData.locations.clockIn ? `${sessionData.locations.clockIn.lat}, ${sessionData.locations.clockIn.lon}` : 'N/A',
                        locationOut: sessionData.locations.clockOut ? `${sessionData.locations.clockOut.lat}, ${sessionData.locations.clockOut.lon}` : 'N/A',
                        procedures: procedureData,
                        hourlyPay: hourlyPay.toFixed(2),
                        commissionPay: commissionPay.toFixed(2),
                        totalPay: totalPay.toFixed(2)
                    };

                    if (GOOGLE_SCRIPT_URL && GOOGLE_SCRIPT_URL.startsWith('http')) {
                         try {
                            await fetch(GOOGLE_SCRIPT_URL, {
                                method: 'POST',
                                mode: 'no-cors',
                                cache: 'no-cache',
                                headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify(payload)
                            });
                        } catch(err) {
                            console.error("Error sending to Google Sheet:", err);
                        }
                    }

                    clockOutBtn.innerHTML = originalText;
                    updateUI();
                }
            });

            procedureTracker.addEventListener('click', (e) => {
                const button = e.target.closest('button');
                if (!button) return;
                const { action, target } = button.dataset;
                if (!action || !target) return;
                const input = document.getElementById(`${target}-count`);
                let currentValue = parseInt(input.value, 10);
                if (action === 'increment') currentValue++;
                else if (action === 'decrement' && currentValue > 0) currentValue--;
                input.value = currentValue;
            });

            // --- Initial Setup ---
            populateProcedureTracker();
            checkLoginState();
        });
    </script>
</body>
</html>

