{
  "name": "Timesheet Pro",
  "description": "A professional time clock and procedure tracking application for medical staff.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Employee {
  name: string;
  rate: number;
}

export interface Procedure {
  name: string;
  value: number;
}

export interface GeoLocation {
  lat: number;
  lon: number;
}

export interface ProcedureCounts {
  [key: string]: number;
}

export interface Session {
  id: string;
  clockIn: string; // ISO Date String
  clockOut: string; // ISO Date String
  locations: {
    clockIn: GeoLocation | null;
    clockOut: GeoLocation | null;
  };
  procedures: ProcedureCounts;
  earnings: {
    hourly: number;
    commission: number;
    total: number;
  };
}

export interface EmployeeData {
  currentClockIn: {
    time: string;
    location: GeoLocation | null;
  } | null;
  history: Session[];
}

export interface AppData {
  [email: string]: EmployeeData;
}

export interface GoogleSheetPayload {
  employeeName: string;
  clockIn: string;
  clockOut: string;
  totalHours: string;
  locationIn: string;
  locationOut: string;
  procedures: ProcedureCounts;
  hourlyPay: string;
  commissionPay: string;
  totalPay: string;
}

import { Employee, Procedure } from './types';

export const GOOGLE_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbwa6_SJQ1IObCEJrw3D0DDvNP8mzUNeWmyl0v9c05RmPAV1TTKKwrSeAeulssaJGBar/exec';

export const APP_STORAGE_KEY = 'employeeTimeClockData_v2';
export const SESSION_KEY = 'loggedInUserEmail_v2';

export const EMPLOYEES: Record<string, Employee> = {
  'ikdilley@gmail.com': { name: 'Isaac Dilley', rate: 50 },
  'btdilley@gmail.com': { name: 'Brian Dilley', rate: 100 },
  'dilleyog@gmail.com': { name: 'Oliva Dilley', rate: 49 }
};

export const PROCEDURES: Record<string, Procedure> = {
  'Glutithione': { name: 'Glutithione', value: 20 },
  'IV': { name: 'IV', value: 50 },
  'Laser': { name: 'Laser', value: 15 }
};

import { GeoLocation, ProcedureCounts, Procedure } from "./types";

export const formatTime = (dateStr: string): string => {
  if (!dateStr) return '';
  return new Date(dateStr).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true });
};

export const formatDate = (dateStr: string): string => {
  if (!dateStr) return '';
  return new Date(dateStr).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
};

export const formatDuration = (ms: number): string => {
  if (ms < 0) ms = 0;
  const s = Math.floor(ms / 1000);
  const m = Math.floor(s / 60);
  const h = Math.floor(m / 60);
  return `${h}h ${m % 60}m ${s % 60}s`;
};

export const formatCurrency = (amount: number): string => {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(amount);
};

export const calculateEarnings = (
  clockInStr: string,
  clockOutStr: string,
  rate: number,
  proceduresCount: ProcedureCounts,
  procedureDefinitions: Record<string, Procedure>
) => {
  const start = new Date(clockInStr).getTime();
  const end = new Date(clockOutStr).getTime();
  const durationMs = end - start;
  const hours = durationMs / (1000 * 60 * 60);

  const hourlyPay = hours * rate;

  let commissionPay = 0;
  Object.entries(proceduresCount).forEach(([key, count]) => {
    const procDef = procedureDefinitions[key];
    if (procDef) {
      commissionPay += procDef.value * count;
    }
  });

  return {
    hourly: hourlyPay,
    commission: commissionPay,
    total: hourlyPay + commissionPay,
    hours
  };
};

export const getGeoLocation = (): Promise<GeoLocation | null> => {
  return new Promise((resolve) => {
    if (!navigator.geolocation) {
      resolve(null);
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (position) => {
        resolve({ lat: position.coords.latitude, lon: position.coords.longitude });
      },
      (error) => {
        console.error("Geo error:", error);
        resolve(null);
      }
    );
  });
};

import React from 'react';
import { Loader2 } from 'lucide-react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  isLoading?: boolean;
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  children: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  isLoading, 
  variant = 'primary', 
  children, 
  className = '', 
  disabled,
  ...props 
}) => {

  const baseStyles = "w-full py-3 px-4 rounded-lg transition duration-300 ease-in-out font-bold flex justify-center items-center gap-2 transform active:scale-95";

  const variants = {
    primary: "bg-indigo-600 hover:bg-indigo-700 text-white shadow-md hover:shadow-lg",
    secondary: "bg-gray-600 hover:bg-gray-700 text-white shadow-md",
    danger: "bg-red-500 hover:bg-red-600 text-white",
    ghost: "bg-gray-200 hover:bg-gray-300 text-gray-800",
  };

  return (
    <button 
      disabled={isLoading || disabled}
      className={`${baseStyles} ${variants[variant]} ${disabled ? 'opacity-50 cursor-not-allowed hover:transform-none' : 'hover:scale-[1.02]'} ${className}`}
