import React from 'react';
import { PROCEDURES } from '../constants';
import { ProcedureCounts } from '../types';
import { Minus, Plus } from 'lucide-react';

interface ProcedureTrackerProps {
  counts: ProcedureCounts;
  onChange: (newCounts: ProcedureCounts) => void;
}

export const ProcedureTracker: React.FC<ProcedureTrackerProps> = ({ counts, onChange }) => {

  const handleIncrement = (key: string) => {
    onChange({
      ...counts,
      [key]: (counts[key] || 0) + 1
    });
  };

  const handleDecrement = (key: string) => {
    if (!counts[key] || counts[key] <= 0) return;
    onChange({
      ...counts,
      [key]: counts[key] - 1
    });
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
      <div className="bg-gray-50 px-4 py-3 border-b border-gray-100">
        <h3 className="text-lg font-semibold text-gray-800">Session Procedures</h3>
        <p className="text-xs text-gray-500">Track performable items for commission</p>
      </div>
      <div className="p-4 space-y-4">
        {Object.keys(PROCEDURES).map((key) => (
          <div key={key} className="flex justify-between items-center group">
            <div className="flex flex-col">
              <span className="font-medium text-gray-700">{PROCEDURES[key].name}</span>
              <span className="text-xs text-gray-400 font-mono">${PROCEDURES[key].value.toFixed(2)}</span>
            </div>
            <div className="flex items-center gap-3">
              <button
                onClick={() => handleDecrement(key)}
                className="w-8 h-8 flex items-center justify-center rounded-full bg-gray-100 text-gray-600 hover:bg-gray-200 transition active:bg-gray-300"
                aria-label="Decrease count"
              >
                <Minus size={16} />
              </button>
              <div className="w-12 text-center font-bold text-lg text-indigo-900">
                {counts[key] || 0}
              </div>
              <button
                onClick={() => handleIncrement(key)}
                className="w-8 h-8 flex items-center justify-center rounded-full bg-indigo-50 text-indigo-600 hover:bg-indigo-100 transition active:bg-indigo-200"
                aria-label="Increase count"
              >
                <Plus size={16} />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

