export interface GoogleSheetPayload {
  employeeName: string;
  clockIn: string;
  clockOut: string;
  totalHours: string;
  locationIn: string;
  locationOut: string;
  procedures: ProcedureCounts;
  hourlyPay: string;
  bonusPay: string;
  totalPay: string;
}

import { GeoLocation, ProcedureCounts, Procedure } from "./types";

export const formatTime = (dateStr: string): string => {
  if (!dateStr) return '';
  return new Date(dateStr).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true });
};

export const formatDate = (dateStr: string): string => {
  if (!dateStr) return '';
  return new Date(dateStr).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
};

export const formatDuration = (ms: number): string => {
  if (ms < 0) ms = 0;
  const s = Math.floor(ms / 1000);
  const m = Math.floor(s / 60);
  const h = Math.floor(m / 60);
  return `${h}h ${m % 60}m ${s % 60}s`;
};

export const formatCurrency = (amount: number): string => {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(amount);
};

export const calculateEarnings = (
  clockInStr: string,
  clockOutStr: string,
  rate: number,
  proceduresCount: ProcedureCounts,
  procedureDefinitions: Record<string, Procedure>
) => {
  const start = new Date(clockInStr).getTime();
  const end = new Date(clockOutStr).getTime();
  const durationMs = end - start;
  const hours = durationMs / (1000 * 60 * 60);

  const hourlyPay = hours * rate;

  let bonusPay = 0;
  Object.entries(proceduresCount).forEach(([key, count]) => {
    const procDef = procedureDefinitions[key];
    if (procDef) {
      bonusPay += procDef.value * count;
    }
  });

  return {
    hourly: hourlyPay,
    bonus: bonusPay,
    total: hourlyPay + bonusPay,
    hours
  };
};

export const getGeoLocation = (): Promise<GeoLocation | null> => {
  return new Promise((resolve) => {
    if (!navigator.geolocation) {
      resolve(null);
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (position) => {
        resolve({ lat: position.coords.latitude, lon: position.coords.longitude });
      },
      (error) => {
        console.error("Geo error:", error);
        resolve(null);
      }
    );
  });
};

import React from 'react';
import { PROCEDURES } from '../constants';
import { ProcedureCounts } from '../types';
import { Minus, Plus } from 'lucide-react';

interface ProcedureTrackerProps {
  counts: ProcedureCounts;
  onChange: (newCounts: ProcedureCounts) => void;
}

export const ProcedureTracker: React.FC<ProcedureTrackerProps> = ({ counts, onChange }) => {

  const handleIncrement = (key: string) => {
    onChange({
      ...counts,
      [key]: (counts[key] || 0) + 1
    });
  };

  const handleDecrement = (key: string) => {
    if (!counts[key] || counts[key] <= 0) return;
    onChange({
      ...counts,
      [key]: counts[key] - 1
    });
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
      <div className="bg-gray-50 px-5 py-4 border-b border-gray-100">
        <h3 className="text-base font-bold text-gray-800">Session Procedures</h3>
        <p className="text-xs text-gray-500 mt-0.5">Track performable items for bonus</p>
      </div>
      <div className="p-2">
        {Object.keys(PROCEDURES).map((key) => (
          <div key={key} className="flex justify-between items-center p-3 hover:bg-gray-50 rounded-lg transition-colors">
            <div className="flex flex-col">
              <span className="font-semibold text-gray-700 text-sm">{PROCEDURES[key].name}</span>
              <span className="text-xs text-gray-400 font-medium tracking-wide">${PROCEDURES[key].value.toFixed(2)}</span>
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={() => handleDecrement(key)}
                className="w-7 h-7 flex items-center justify-center rounded-full bg-gray-100 text-gray-600 hover:bg-gray-200 transition active:bg-gray-300"
                aria-label="Decrease count"
              >
                <Minus size={14} />
              </button>
              <div className="w-8 text-center font-bold text-sm text-indigo-900">
                {counts[key] || 0}
              </div>
              <button
                onClick={() => handleIncrement(key)}
                className="w-7 h-7 flex items-center justify-center rounded-full bg-indigo-50 text-indigo-600 hover:bg-indigo-100 transition active:bg-indigo-200"
                aria-label="Increase count"
              >
                <Plus size={14} />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

