import React from 'react';
import { PROCEDURES } from '../constants';
import { ProcedureCounts } from '../types';
import { Minus, Plus } from 'lucide-react';

interface ProcedureTrackerProps {
  counts: ProcedureCounts;
  onChange: (newCounts: ProcedureCounts) => void;
  employeeCategory: string;
}

export const ProcedureTracker: React.FC<ProcedureTrackerProps> = ({ counts, onChange, employeeCategory }) => {

  const handleIncrement = (key: string) => {
    onChange({
      ...counts,
      [key]: (counts[key] || 0) + 1
    });
  };

  const handleDecrement = (key: string) => {
    if (!counts[key] || counts[key] <= 0) return;
    onChange({
      ...counts,
      [key]: counts[key] - 1
    });
  };

  // Filter procedures that match the employee's category
  const visibleProcedures = Object.entries(PROCEDURES).filter(
    ([_, proc]) => proc.category === employeeCategory
  );

  if (visibleProcedures.length === 0) {
    return (
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 text-center">
            <p className="text-gray-400 text-sm">No procedures available for your category ({employeeCategory}).</p>
        </div>
    );
  }

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
      <div className="bg-gray-50 px-5 py-4 border-b border-gray-100">
        <h3 className="text-base font-bold text-gray-800">Session Procedures</h3>
        <p className="text-xs text-gray-500 mt-0.5">Track items for bonus pay</p>
      </div>
      <div className="p-2 max-h-[400px] overflow-y-auto">
        {visibleProcedures.map(([key, proc]) => (
          <div key={key} className="flex justify-between items-center p-3 hover:bg-gray-50 rounded-lg transition-colors">
            <div className="flex flex-col">
              <span className="font-semibold text-gray-700 text-sm">{proc.name}</span>
              <span className="text-xs text-gray-400 font-medium tracking-wide">${proc.value.toFixed(2)}</span>
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={() => handleDecrement(key)}
                className="w-7 h-7 flex items-center justify-center rounded-full bg-gray-100 text-gray-600 hover:bg-gray-200 transition active:bg-gray-300"
                aria-label="Decrease count"
              >
                <Minus size={14} />
              </button>
              <div className="w-8 text-center font-bold text-sm text-indigo-900">
                {counts[key] || 0}
              </div>
              <button
                onClick={() => handleIncrement(key)}
                className="w-7 h-7 flex items-center justify-center rounded-full bg-indigo-50 text-indigo-600 hover:bg-indigo-100 transition active:bg-indigo-200"
                aria-label="Increase count"
              >
                <Plus size={14} />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { EMPLOYEES, GOOGLE_SCRIPT_URL, PROCEDURES, APP_STORAGE_KEY } from '../constants';
import { AppData, EmployeeData, ProcedureCounts, Session, GoogleSheetPayload } from '../types';
import { getGeoLocation, calculateEarnings, formatTime, formatCurrency } from '../utils';
import { Button } from './ui/Button';
import { ProcedureTracker } from './ProcedureTracker';
import { HistoryList } from './HistoryList';
import { ClockOutModal } from './ClockOutModal';
import { MapPin, LogOut, PlayCircle, StopCircle } from 'lucide-react';

interface DashboardProps {
  email: string;
  onLogout: () => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ email, onLogout }) => {
  const employee = EMPLOYEES[email];
  const [data, setData] = useState<EmployeeData>({ currentClockIn: null, history: [] });
  const [currentProcedures, setCurrentProcedures] = useState<ProcedureCounts>({});
  const [isLoading, setIsLoading] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Load data on mount
  useEffect(() => {
    const stored = localStorage.getItem(APP_STORAGE_KEY);
    if (stored) {
      const parsed: AppData = JSON.parse(stored);
      if (parsed[email]) {
        setData(parsed[email]);
      }
    }
  }, [email]);

  // Persist data whenever it changes
  useEffect(() => {
    const stored = localStorage.getItem(APP_STORAGE_KEY);
    const parsed: AppData = stored ? JSON.parse(stored) : {};
    parsed[email] = data;
    localStorage.setItem(APP_STORAGE_KEY, JSON.stringify(parsed));
  }, [data, email]);

  const handleClockIn = async () => {
    setIsLoading(true);
    try {
      const location = await getGeoLocation();
      const now = new Date().toISOString();

      setData(prev => ({
        ...prev,
        currentClockIn: {
          time: now,
          location
        }
      }));
      setCurrentProcedures({});
    } catch (e) {
      alert("Failed to clock in. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const initiateClockOut = () => {
    setIsModalOpen(true);
  };

  const confirmClockOut = async () => {
    if (!data.currentClockIn) return;
    setIsLoading(true);

    try {
        const location = await getGeoLocation();
        const clockOutTime = new Date().toISOString();
        const earnings = calculateEarnings(
            data.currentClockIn.time, 
            clockOutTime, 
            employee.rate, 
            currentProcedures, 
            PROCEDURES
        );

        const newSession: Session = {
            id: crypto.randomUUID(),
            clockIn: data.currentClockIn.time,
            clockOut: clockOutTime,
            locations: {
                clockIn: data.currentClockIn.location,
                clockOut: location
            },
            procedures: currentProcedures,
            earnings: {
                hourly: earnings.hourly,
                bonus: earnings.bonus,
                total: earnings.total
            }
        };

        // Prepare Payload
        // We create a base payload, then spread individual procedures into it
        const payload: GoogleSheetPayload = {
            employeeName: employee.name,
            category: employee.category,
            clockIn: formatTime(newSession.clockIn),
            clockOut: formatTime(newSession.clockOut),
            totalHours: earnings.hours.toFixed(2),
            locationIn: newSession.locations.clockIn ? `${newSession.locations.clockIn.lat}, ${newSession.locations.clockIn.lon}` : 'N/A',
            locationOut: newSession.locations.clockOut ? `${newSession.locations.clockOut.lat}, ${newSession.locations.clockOut.lon}` : 'N/A',
            hourlyPay: earnings.hourly.toFixed(2),
            bonusPay: earnings.bonus.toFixed(2),
            totalPay: earnings.total.toFixed(2)
        };

        // Flatten procedures into the payload: "Procedure Name (Category)" -> count
        Object.entries(PROCEDURES).forEach(([key, def]) => {
            const count = currentProcedures[key] || 0;
            // Only add to payload if count > 0 to keep request smaller, OR add all if you want empty columns. 
            // The Google Script logic will handle missing keys by leaving cells blank.
            if (count > 0) {
                payload[`${def.name} [${def.category}]`] = count;
            }
        });

        // Fire and forget fetch to Google Scripts (no-cors)
        fetch(GOOGLE_SCRIPT_URL, {
            method: 'POST',
            mode: 'no-cors',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        }).catch(err => console.error("API Error", err));

        setData(prev => ({
            currentClockIn: null,
            history: [...prev.history, newSession]
        }));

        setIsModalOpen(false);
        setCurrentProcedures({});

    } catch (e) {
        console.error(e);
        alert("Error during clock out.");
    } finally {
        setIsLoading(false);
    }
  };

  const isClockedIn = !!data.currentClockIn;

  return (
    <div className="w-full max-w-3xl mx-auto px-4 py-6 space-y-6">

      {/* Header */}
      <div className="bg-white rounded-2xl shadow-sm p-6 flex flex-col md:flex-row justify-between items-center gap-4">
        <div className="flex items-center gap-4">
            <img src="https://i.imgur.com/52HoFpA.png" alt="Logo" className="h-16 w-auto" />
            <div>
                <h1 className="text-2xl font-bold text-gray-800">Welcome, {employee.name.split(' ')[0]}</h1>
                <p className="text-sm text-gray-500 flex items-center gap-1">
                   <MapPin size={12} /> Geolocating when Starting and Ending Shift
                </p>
            </div>
        </div>
        <button onClick={onLogout} className="text-sm text-gray-600 hover:text-red-600 flex items-center gap-1 transition-colors">
            <LogOut size={14} /> Sign Out
        </button>
      </div>

      {/* Status Card */}
      <div className={`rounded-xl p-6 text-white text-center shadow-lg transition-colors duration-500 ${isClockedIn ? 'bg-gradient-to-r from-indigo-500 to-purple-600' : 'bg-gray-700'}`}>
         <p className="text-sm opacity-80 font-medium tracking-wider uppercase mb-1">Current Status</p>
         <h2 className="text-3xl font-bold mb-4 flex items-center justify-center gap-3">
            {isClockedIn ? (
                <>
                    <PlayCircle size={32} /> Clocked In
                </>
            ) : (
                <>
                    <StopCircle size={32} /> Off Duty
                </>
            )}
         </h2>

         {!isClockedIn ? (
             <Button 
                onClick={handleClockIn} 
                isLoading={isLoading} 
                variant="white"
                className="max-w-xs mx-auto"
            >
                Start Shift
             </Button>
         ) : (
             <Button 
                onClick={initiateClockOut} 
                variant="whiteDanger" 
                className="max-w-xs mx-auto"
            >
                End Shift
             </Button>
         )}
      </div>

      {/* Main Content Area */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">

        {/* Left Col: Procedures (Only visible when clocked in) */}
        {isClockedIn && (
            <div className="md:col-span-1">
                 <ProcedureTracker 
                    counts={currentProcedures} 
                    onChange={setCurrentProcedures} 
                    employeeCategory={employee.category}
                 />
            </div>
        )}

        {/* Right Col: History */}
        <div className={`${isClockedIn ? 'md:col-span-2' : 'md:col-span-3'} space-y-4`}>
            <h2 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                Work History
            </h2>
            <div className="max-h-[600px] overflow-y-auto pr-2">
                <HistoryList history={data.history} />
            </div>
        </div>
      </div>

      <ClockOutModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onConfirm={confirmClockOut}
        procedures={currentProcedures}
        isProcessing={isLoading}
      />
    </div>
  );
};

