function doPost(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    var doc = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = doc.getSheetByName('TimeLog');

    // Create sheet if it doesn't exist
    if (!sheet) {
      sheet = doc.insertSheet('TimeLog');
      // Initial Headers
      sheet.appendRow(['Timestamp', 'Employee Name', 'Category', 'Clock In', 'Clock Out', 'Total Hours', 'Hourly Pay', 'Bonus Pay', 'Total Pay', 'Location In', 'Location Out']);
    }

    // Parse data from request
    var rawData = e.postData.contents;
    var data = JSON.parse(rawData);

    // Standard fields that always exist
    var rowData = {
      'Timestamp': new Date(),
      'Employee Name': data.employeeName,
      'Category': data.category,
      'Clock In': data.clockIn,
      'Clock Out': data.clockOut,
      'Total Hours': data.totalHours,
      'Hourly Pay': data.hourlyPay,
      'Bonus Pay': data.bonusPay,
      'Total Pay': data.totalPay,
      'Location In': data.locationIn,
      'Location Out': data.locationOut
    };

    // Get current headers from the sheet
    var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];

    // Check for new dynamic procedure keys in the incoming data
    // Any key in 'data' that isn't a standard field is treated as a procedure column
    var standardKeys = ['employeeName', 'category', 'clockIn', 'clockOut', 'totalHours', 'locationIn', 'locationOut', 'procedures', 'hourlyPay', 'bonusPay', 'totalPay'];

    for (var key in data) {
      if (standardKeys.indexOf(key) === -1) {
        // This is a procedure key (e.g., "Botox [INJ]")
        // If this header doesn't exist, add it
        if (headers.indexOf(key) === -1) {
          sheet.getRange(1, headers.length + 1).setValue(key);
          headers.push(key); // Update local headers array
        }
        // Add the value to our rowData object mapping
        rowData[key] = data[key];
      }
    }

    // Construct the final array for the new row based on header order
    var newRow = headers.map(function(header) {
      return rowData[header] || ''; // Return value or empty string if undefined
    });

    // Append the row
    sheet.appendRow(newRow);

    return ContentService.createTextOutput(JSON.stringify({ 'result': 'success', 'row': newRow.length }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (e) {
    return ContentService.createTextOutput(JSON.stringify({ 'result': 'error', 'error': e }))
      .setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

