function doPost(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(30000); // Increased lock time for image processing

  try {
    var doc = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = doc.getSheetByName('TimeLog');

    if (!sheet) {
      sheet = doc.insertSheet('TimeLog');
      sheet.appendRow(['Timestamp', 'Employee Name', 'Category', 'Clock In', 'Clock Out', 'Total Hours', 'Hourly Pay', 'Bonus Pay', 'Total Pay', 'Location In', 'Location Out', 'Photo In', 'Photo Out']);
    }

    var rawData = e.postData.contents;
    var data = JSON.parse(rawData);

    // --- Image Handling ---
    var folderName = "TimeClock_Photos";
    var folder;
    var folders = DriveApp.getFoldersByName(folderName);
    if (folders.hasNext()) {
      folder = folders.next();
    } else {
      folder = DriveApp.createFolder(folderName);
    }

    var photoInUrl = "";
    if (data.photoIn) {
      photoInUrl = saveImage(data.photoIn, data.employeeName + "_IN_" + new Date().getTime(), folder);
    }

    var photoOutUrl = "";
    if (data.photoOut) {
      photoOutUrl = saveImage(data.photoOut, data.employeeName + "_OUT_" + new Date().getTime(), folder);
    }
    // ----------------------

    var rowData = {
      'Timestamp': new Date(),
      'Employee Name': data.employeeName,
      'Category': data.category,
      'Clock In': data.clockIn,
      'Clock Out': data.clockOut,
      'Total Hours': data.totalHours,
      'Hourly Pay': data.hourlyPay,
      'Bonus Pay': data.bonusPay,
      'Total Pay': data.totalPay,
      'Location In': data.locationIn,
      'Location Out': data.locationOut,
      'Photo In': photoInUrl,
      'Photo Out': photoOutUrl
    };

    var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];

    // Check for standard keys plus new Photo keys
    var standardKeys = ['employeeName', 'category', 'clockIn', 'clockOut', 'totalHours', 'locationIn', 'locationOut', 'photoIn', 'photoOut', 'procedures', 'hourlyPay', 'bonusPay', 'totalPay'];

    for (var key in data) {
      if (standardKeys.indexOf(key) === -1) {
        if (headers.indexOf(key) === -1) {
          sheet.getRange(1, headers.length + 1).setValue(key);
          headers.push(key);
        }
        rowData[key] = data[key];
      }
    }

    // Ensure Photo columns exist if they weren't in the sheet before
    if (headers.indexOf('Photo In') === -1) {
        sheet.getRange(1, headers.length + 1).setValue('Photo In');
        headers.push('Photo In');
    }
    if (headers.indexOf('Photo Out') === -1) {
        sheet.getRange(1, headers.length + 1).setValue('Photo Out');
        headers.push('Photo Out');
    }

    var newRow = headers.map(function(header) {
      return rowData[header] || '';
    });

    sheet.appendRow(newRow);

    return ContentService.createTextOutput(JSON.stringify({ 'result': 'success' }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (e) {
    return ContentService.createTextOutput(JSON.stringify({ 'result': 'error', 'error': e.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

function saveImage(base64String, fileName, folder) {
  try {
    // base64String usually comes in as "data:image/jpeg;base64,......."
    // We need to strip the metadata prefix
    var cleanBase64 = base64String.split(',')[1];
    var decoded = Utilities.base64Decode(cleanBase64);
    var blob = Utilities.newBlob(decoded, MimeType.JPEG, fileName + ".jpg");
    var file = folder.createFile(blob);
    // Allow anyone with link to view (optional, adjust as needed for privacy)
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW); 
    return file.getUrl();
  } catch (e) {
    return "Error saving image: " + e.toString();
  }
}

import { GeoLocation, ProcedureCounts, Procedure } from "./types";

export const formatTime = (dateStr: string): string => {
  if (!dateStr) return '';
  return new Date(dateStr).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true });
};

export const formatDate = (dateStr: string): string => {
  if (!dateStr) return '';
  return new Date(dateStr).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
};

export const formatDuration = (ms: number): string => {
  if (ms < 0) ms = 0;
  const s = Math.floor(ms / 1000);
  const m = Math.floor(s / 60);
  const h = Math.floor(m / 60);
  return `${h}h ${m % 60}m ${s % 60}s`;
};

export const formatCurrency = (amount: number): string => {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(amount);
};

export const calculateEarnings = (
  clockInStr: string,
  clockOutStr: string,
  rate: number,
  proceduresCount: ProcedureCounts,
  procedureDefinitions: Record<string, Procedure>
) => {
  const start = new Date(clockInStr).getTime();
  const end = new Date(clockOutStr).getTime();
  const durationMs = end - start;
  const hours = durationMs / (1000 * 60 * 60);

  const hourlyPay = hours * rate;

  let bonusPay = 0;
  Object.entries(proceduresCount).forEach(([key, count]) => {
    const procDef = procedureDefinitions[key];
    if (procDef) {
      bonusPay += procDef.value * count;
    }
  });

  return {
    hourly: hourlyPay,
    bonus: bonusPay,
    total: hourlyPay + bonusPay,
    hours
  };
};

export const getGeoLocation = (): Promise<GeoLocation | null> => {
  return new Promise((resolve) => {
    if (!navigator.geolocation) {
      resolve(null);
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (position) => {
        resolve({ lat: position.coords.latitude, lon: position.coords.longitude });
      },
      (error) => {
        console.error("Geo error:", error);
        resolve(null);
      }
    );
  });
};

export const capturePhoto = async (): Promise<string | null> => {
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ 
      video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
    });

    // We need to create a temporary video element to grab a frame if grabFrame isn't supported 
    // or just use a canvas drawing method which is more universally supported
    const video = document.createElement('video');
    video.srcObject = stream;

    return new Promise((resolve) => {
        video.onloadedmetadata = () => {
            video.play();
            // Wait a moment for camera to adjust light
            setTimeout(() => {
                const canvas = document.createElement('canvas');
                canvas.width = video.videoWidth;
                canvas.height = video.videoHeight;
                const ctx = canvas.getContext('2d');
                if (ctx) {
                    ctx.drawImage(video, 0, 0);
                    const dataUrl = canvas.toDataURL('image/jpeg', 0.7); // Compress slightly

                    // Stop tracks
                    stream.getTracks().forEach(t => t.stop());
                    resolve(dataUrl);
                } else {
                    stream.getTracks().forEach(t => t.stop());
                    resolve(null);
                }
            }, 500);
        };
        video.onerror = () => {
             stream.getTracks().forEach(t => t.stop());
             resolve(null);
        }
    });

  } catch (err) {
    console.error("Camera error:", err);
    // Return null if user denies permission or camera fails
    return null; 
  }
};

