function doPost(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(30000); // Increased lock time for image processing

  try {
    var doc = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = doc.getSheetByName('TimeLog');

    if (!sheet) {
      sheet = doc.insertSheet('TimeLog');
      sheet.appendRow(['Timestamp', 'Employee Name', 'Category', 'Clock In', 'Clock Out', 'Total Hours', 'Hourly Pay', 'Bonus Pay', 'Total Pay', 'Location In', 'Location Out', 'Signature In', 'Signature Out']);
    }

    var rawData = e.postData.contents;
    var data = JSON.parse(rawData);

    // --- Image Handling ---
    var folderName = "TimeClock_Signatures";
    var folder;
    var folders = DriveApp.getFoldersByName(folderName);
    if (folders.hasNext()) {
      folder = folders.next();
    } else {
      folder = DriveApp.createFolder(folderName);
    }

    var signatureInUrl = "";
    if (data.signatureIn) {
      signatureInUrl = saveImage(data.signatureIn, data.employeeName + "_SIG_IN_" + new Date().getTime(), folder);
    }

    var signatureOutUrl = "";
    if (data.signatureOut) {
      signatureOutUrl = saveImage(data.signatureOut, data.employeeName + "_SIG_OUT_" + new Date().getTime(), folder);
    }
    // ----------------------

    var rowData = {
      'Timestamp': new Date(),
      'Employee Name': data.employeeName,
      'Category': data.category,
      'Clock In': data.clockIn,
      'Clock Out': data.clockOut,
      'Total Hours': data.totalHours,
      'Hourly Pay': data.hourlyPay,
      'Bonus Pay': data.bonusPay,
      'Total Pay': data.totalPay,
      'Location In': data.locationIn,
      'Location Out': data.locationOut,
      'Signature In': signatureInUrl,
      'Signature Out': signatureOutUrl
    };

    var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];

    // Check for standard keys plus new Signature keys
    var standardKeys = ['employeeName', 'category', 'clockIn', 'clockOut', 'totalHours', 'locationIn', 'locationOut', 'signatureIn', 'signatureOut', 'procedures', 'hourlyPay', 'bonusPay', 'totalPay'];

    for (var key in data) {
      if (standardKeys.indexOf(key) === -1) {
        if (headers.indexOf(key) === -1) {
          sheet.getRange(1, headers.length + 1).setValue(key);
          headers.push(key);
        }
        rowData[key] = data[key];
      }
    }

    // Ensure Signature columns exist if they weren't in the sheet before
    if (headers.indexOf('Signature In') === -1) {
        sheet.getRange(1, headers.length + 1).setValue('Signature In');
        headers.push('Signature In');
    }
    if (headers.indexOf('Signature Out') === -1) {
        sheet.getRange(1, headers.length + 1).setValue('Signature Out');
        headers.push('Signature Out');
    }

    var newRow = headers.map(function(header) {
      return rowData[header] || '';
    });

    sheet.appendRow(newRow);

    return ContentService.createTextOutput(JSON.stringify({ 'result': 'success' }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (e) {
    return ContentService.createTextOutput(JSON.stringify({ 'result': 'error', 'error': e.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

function saveImage(base64String, fileName, folder) {
  try {
    // base64String usually comes in as "data:image/jpeg;base64,......." or "data:image/png;base64,...."
    // We need to strip the metadata prefix
    var cleanBase64 = base64String.split(',')[1];
    var decoded = Utilities.base64Decode(cleanBase64);
    var blob = Utilities.newBlob(decoded, MimeType.PNG, fileName + ".png");
    var file = folder.createFile(blob);
    // Allow anyone with link to view (optional, adjust as needed for privacy)
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW); 
    return file.getUrl();
  } catch (e) {
    return "Error saving image: " + e.toString();
  }
}

