function doPost(e) {
  var lock = LockService.getScriptLock();
  // Wait up to 10 seconds for concurrent access
  lock.tryLock(10000); 

  try {
    var rawData = e.postData.contents;
    var data = JSON.parse(rawData);
    var action = data.action;

    // --- HANDLE LOGIN ---
    if (action === 'login') {
      var email = data.email ? data.email.trim() : '';
      var pin = data.pin ? data.pin.trim() : '';

      var employee = EMPLOYEES[email];

      if (employee && employee.pin === pin) {
        // Return success with employee details (excluding PIN) and the procedure list
        var safeEmployee = {
          name: employee.name,
          category: employee.category,
          rate: employee.rate
        };

        return ContentService.createTextOutput(JSON.stringify({ 
          'result': 'success',
          'employee': safeEmployee,
          'procedures': PROCEDURES 
        })).setMimeType(ContentService.MimeType.JSON);

      } else {
        return ContentService.createTextOutput(JSON.stringify({ 
          'result': 'error', 
          'error': 'Invalid email or PIN' 
        })).setMimeType(ContentService.MimeType.JSON);
      }
    }

    // --- HANDLE CLOCK OUT (DEFAULT) ---
    var doc = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = doc.getSheetByName('TimeLog');

    if (!sheet) {
      sheet = doc.insertSheet('TimeLog');
      sheet.appendRow(['Timestamp', 'Employee Name', 'Category', 'Clock In', 'Clock Out', 'Total Hours', 'Hourly Pay', 'Bonus Pay', 'Total Pay', 'Location In', 'Location Out']);
    }

    var rowData = {
      'Timestamp': new Date(),
      'Employee Name': data.employeeName,
      'Category': data.category,
      'Clock In': data.clockIn,
      'Clock Out': data.clockOut,
      'Total Hours': data.totalHours,
      'Hourly Pay': data.hourlyPay,
      'Bonus Pay': data.bonusPay,
      'Total Pay': data.totalPay,
      'Location In': data.locationIn,
      'Location Out': data.locationOut
    };

    var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];

    // Check for standard keys to exclude from dynamic procedure columns
    var standardKeys = ['action', 'employeeName', 'category', 'clockIn', 'clockOut', 'totalHours', 'locationIn', 'locationOut', 'procedures', 'hourlyPay', 'bonusPay', 'totalPay'];

    for (var key in data) {
      if (standardKeys.indexOf(key) === -1) {
        // Dynamic column for procedures
        if (headers.indexOf(key) === -1) {
          sheet.getRange(1, headers.length + 1).setValue(key);
          headers.push(key);
        }
        rowData[key] = data[key];
      }
    }

    var newRow = headers.map(function(header) {
      return rowData[header] || '';
    });

    sheet.appendRow(newRow);

    return ContentService.createTextOutput(JSON.stringify({ 'result': 'success' }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (e) {
    return ContentService.createTextOutput(JSON.stringify({ 'result': 'error', 'error': e.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

import React, { useState } from 'react';
import { GOOGLE_SCRIPT_URL } from '../constants';
import { Button } from './ui/Button';
import { Employee, Procedure, LoginResponse } from '../types';

interface LoginProps {
  onLogin: (email: string, employee: Employee, procedures: Record<string, Procedure>) => void;
}

export const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [pin, setPin] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const cleanEmail = email.trim();
    const cleanPin = pin.trim();

    if (!cleanEmail || !cleanPin) {
        setError('Please enter both email and PIN.');
        return;
    }

    setIsLoading(true);
    setError('');

    try {
        const payload = {
            action: 'login',
            email: cleanEmail,
            pin: cleanPin
        };

        const response = await fetch(GOOGLE_SCRIPT_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
            body: JSON.stringify(payload)
        });

        if (!response.ok) {
            throw new Error('Network response was not ok');
        }

        const data: LoginResponse = await response.json();

        if (data.result === 'success' && data.employee && data.procedures) {
            onLogin(cleanEmail, data.employee, data.procedures);
        } else {
            setError(data.error || 'Login failed. Please check credentials.');
        }

    } catch (err) {
        console.error('Login error:', err);
        setError('Connection error. Please try again.');
    } finally {
        setIsLoading(false);
    }
  };

  return (
    <div className="w-full max-w-md mx-auto bg-white rounded-2xl shadow-xl p-8 space-y-8 animate-fade-in">
      <div className="text-center">
        <img 
          src="https://i.imgur.com/52HoFpA.png" 
          alt="Logo" 
          className="mx-auto h-32 w-auto mb-6 object-contain"
        />
        <h1 className="text-3xl font-bold text-gray-900 mb-2">Time Sheet</h1>
        <p className="text-gray-500">Secure Employee Login</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div>
          <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-1">
            Email Address
          </label>
          <input
            type="email"
            id="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            className="w-full p-3 bg-gray-50 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition outline-none"
            placeholder="name@company.com"
          />
        </div>

        <div>
          <label htmlFor="pin" className="block text-sm font-medium text-gray-700 mb-1">
            4-Digit PIN
          </label>
          <input
            type="password"
            id="pin"
            value={pin}
            onChange={(e) => setPin(e.target.value)}
            required
            maxLength={4}
            pattern="[0-9]*"
            inputMode="numeric"
            className="w-full p-3 bg-gray-50 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition outline-none tracking-widest text-center text-lg font-bold"
            placeholder="0000"
          />
        </div>

        {error && (
          <div className="p-3 bg-red-50 text-red-600 text-sm rounded-md border border-red-100 flex items-center justify-center">
            {error}
          </div>
        )}

        <Button type="submit" isLoading={isLoading}>
          {isLoading ? 'Verifying...' : 'Login'}
        </Button>
      </form>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Login } from './components/Login';
import { Dashboard } from './components/Dashboard';
import { SESSION_KEY, SECURE_SESSION_DATA_KEY } from './constants';
import { Employee, Procedure } from './types';

interface SecureSession {
  employee: Employee;
  procedures: Record<string, Procedure>;
}

const App: React.FC = () => {
  const [currentUserEmail, setCurrentUserEmail] = useState<string | null>(null);
  const [secureData, setSecureData] = useState<SecureSession | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check session storage for existing login
    const savedEmail = sessionStorage.getItem(SESSION_KEY);
    const savedSecureData = sessionStorage.getItem(SECURE_SESSION_DATA_KEY);

    if (savedEmail && savedSecureData) {
      setCurrentUserEmail(savedEmail);
      try {
        setSecureData(JSON.parse(savedSecureData));
      } catch (e) {
        console.error("Failed to parse secure session data");
        sessionStorage.removeItem(SESSION_KEY);
        sessionStorage.removeItem(SECURE_SESSION_DATA_KEY);
      }
    }
    setLoading(false);
  }, []);

  const handleLogin = (email: string, employee: Employee, procedures: Record<string, Procedure>) => {
    const sessionData = { employee, procedures };

    sessionStorage.setItem(SESSION_KEY, email);
    sessionStorage.setItem(SECURE_SESSION_DATA_KEY, JSON.stringify(sessionData));

    setCurrentUserEmail(email);
    setSecureData(sessionData);
  };

  const handleLogout = () => {
    sessionStorage.removeItem(SESSION_KEY);
    sessionStorage.removeItem(SECURE_SESSION_DATA_KEY);
    setCurrentUserEmail(null);
    setSecureData(null);
  };

  if (loading) {
    return (
        <div className="min-h-screen flex items-center justify-center bg-gray-100">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
        </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100 font-sans text-gray-900">
      {currentUserEmail && secureData ? (
        <Dashboard 
            email={currentUserEmail} 
            employee={secureData.employee}
            procedures={secureData.procedures}
            onLogout={handleLogout} 
        />
      ) : (
        <div className="min-h-screen flex items-center justify-center p-4">
            <Login onLogin={handleLogin} />
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { GOOGLE_SCRIPT_URL, APP_STORAGE_KEY } from '../constants';
import { AppData, EmployeeData, ProcedureCounts, Session, GoogleSheetPayload, Employee, Procedure } from '../types';
import { getGeoLocation, calculateEarnings, formatTime } from '../utils';
import { Button } from './ui/Button';
import { ProcedureTracker } from './ProcedureTracker';
import { HistoryList } from './HistoryList';
import { ClockOutModal } from './ClockOutModal';
import { MapPin, LogOut, PlayCircle, StopCircle, Lock } from 'lucide-react';

interface DashboardProps {
  email: string;
  employee: Employee;
  procedures: Record<string, Procedure>;
  onLogout: () => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ email, employee, procedures, onLogout }) => {
  const [data, setData] = useState<EmployeeData>({ currentClockIn: null, history: [] });
  const [currentProcedures, setCurrentProcedures] = useState<ProcedureCounts>({});
  const [isLoading, setIsLoading] = useState(false);
  const [loadingText, setLoadingText] = useState('');

  // Modals
  const [isClockOutModalOpen, setIsClockOutModalOpen] = useState(false);

  // Load data on mount
  useEffect(() => {
    const stored = localStorage.getItem(APP_STORAGE_KEY);
    if (stored) {
      const parsed: AppData = JSON.parse(stored);
      if (parsed[email]) {
        setData(parsed[email]);
      }
    }
  }, [email]);

  // Persist data whenever it changes
  useEffect(() => {
    const stored = localStorage.getItem(APP_STORAGE_KEY);
    const parsed: AppData = stored ? JSON.parse(stored) : {};
    parsed[email] = data;
    localStorage.setItem(APP_STORAGE_KEY, JSON.stringify(parsed));
  }, [data, email]);

  const handleClockIn = async () => {
    setIsLoading(true);
    setLoadingText('Verifying Location...');
    try {
      const location = await getGeoLocation();
      const now = new Date().toISOString();

      setData(prev => ({
        ...prev,
        currentClockIn: {
          time: now,
          location
        }
      }));
      setCurrentProcedures({});
    } catch (e) {
      alert("Failed to clock in. Please try again.");
    } finally {
      setIsLoading(false);
      setLoadingText('');
    }
  };

  const initiateClockOut = () => {
    setIsClockOutModalOpen(true);
  };

  const syncSession = async (session: Session) => {
      // 1. Construct Payload
      const payload: GoogleSheetPayload = {
          action: 'clockOut', // Explicit action
          employeeName: employee.name,
          category: employee.category,
          clockIn: formatTime(session.clockIn),
          clockOut: formatTime(session.clockOut),
          totalHours: session.earnings.hours.toFixed(2),
          locationIn: session.locations.clockIn ? `${session.locations.clockIn.lat}, ${session.locations.clockIn.lon}` : 'N/A',
          locationOut: session.locations.clockOut ? `${session.locations.clockOut.lat}, ${session.locations.clockOut.lon}` : 'N/A',
          hourlyPay: session.earnings.hourly.toFixed(2),
          bonusPay: session.earnings.bonus.toFixed(2),
          totalPay: session.earnings.total.toFixed(2)
      };

      // Flatten procedures
      Object.entries(procedures).forEach(([key, def]) => {
          const count = session.procedures[key] || 0;
          if (count > 0) {
              payload[`${def.name} [${def.category}]`] = count;
          }
      });

      try {
          // Using text/plain prevents the browser from sending an OPTIONS preflight request.
          const response = await fetch(GOOGLE_SCRIPT_URL, {
              method: 'POST',
              headers: { 'Content-Type': 'text/plain;charset=utf-8' },
              body: JSON.stringify(payload)
          });

          if (!response.ok) {
            throw new Error(`Server returned ${response.status} ${response.statusText}`);
          }

          const result = await response.json();
          if (result.result !== 'success') {
            throw new Error(result.error || 'Unknown script error');
          }

          // If successful (verified by server response), update status to synced
          setData(prev => ({
              ...prev,
              history: prev.history.map(s => s.id === session.id ? { ...s, syncStatus: 'synced' } : s)
          }));
      } catch (e) {
          console.error("Sync failed", e);
          // If network error or script error, update status to failed
          setData(prev => ({
              ...prev,
              history: prev.history.map(s => s.id === session.id ? { ...s, syncStatus: 'failed' } : s)
          }));
      }
  };

  const confirmClockOut = async () => {
    if (!data.currentClockIn) return;
    setIsLoading(true);
    setLoadingText('Processing...');

    try {
        setLoadingText('Verifying Location...');
        const location = await getGeoLocation();

        const clockOutTime = new Date().toISOString();
        const earnings = calculateEarnings(
            data.currentClockIn.time, 
            clockOutTime, 
            employee.rate, 
            currentProcedures, 
            procedures
        );

        const newSession: Session = {
            id: crypto.randomUUID(),
            clockIn: data.currentClockIn.time,
            clockOut: clockOutTime,
            locations: {
                clockIn: data.currentClockIn.location,
                clockOut: location
            },
            procedures: currentProcedures,
            earnings: {
                hourly: earnings.hourly,
                bonus: earnings.bonus,
                total: earnings.total,
                hours: earnings.hours
            },
            syncStatus: 'pending'
        };

        // --- OPTIMISTIC UPDATE: SAVE LOCALLY FIRST ---
        setData(prev => ({
            currentClockIn: null,
            history: [...prev.history, newSession]
        }));

        // Reset UI immediately
        setIsClockOutModalOpen(false);
        setCurrentProcedures({});
        setIsLoading(false);
        setLoadingText('');

        // --- ATTEMPT SYNC IN BACKGROUND ---
        await syncSession(newSession);

    } catch (e) {
        console.error(e);
        alert("Error during clock out.");
        setIsLoading(false);
        setLoadingText('');
    }
  };

  const handleRetrySync = async (session: Session) => {
      // Set to pending while retrying
      setData(prev => ({
          ...prev,
          history: prev.history.map(s => s.id === session.id ? { ...s, syncStatus: 'pending' } : s)
      }));
      await syncSession(session);
  };

  const isClockedIn = !!data.currentClockIn;

  return (
    <div className="w-full max-w-3xl mx-auto px-4 py-6 space-y-6">

      {/* Header */}
      <div className="bg-white rounded-2xl shadow-sm p-6 flex flex-col md:flex-row justify-between items-center gap-4">
        <div className="flex items-center gap-4">
            <img src="https://i.imgur.com/52HoFpA.png" alt="Logo" className="h-16 w-auto" />
            <div>
                <h1 className="text-2xl font-bold text-gray-800">Welcome, {employee.name.split(' ')[0]}</h1>
                <div className="flex flex-col gap-1">
                    <p className="text-xs text-gray-500 flex items-center gap-1">
                        <MapPin size={12} /> Geolocating on clock actions
                    </p>
                    <p className="text-xs text-gray-500 flex items-center gap-1">
                        <Lock size={12} /> Secure Session Active
                    </p>
                </div>
            </div>
        </div>
        <button onClick={onLogout} className="text-sm text-gray-600 hover:text-red-600 flex items-center gap-1 transition-colors">
            <LogOut size={14} /> Sign Out
        </button>
      </div>

      {/* Status Card */}
      <div className={`rounded-xl p-6 text-white text-center shadow-lg transition-colors duration-500 ${isClockedIn ? 'bg-gradient-to-r from-indigo-500 to-purple-600' : 'bg-gray-700'}`}>
         <p className="text-sm opacity-80 font-medium tracking-wider uppercase mb-1">Current Status</p>
         <h2 className="text-3xl font-bold mb-4 flex items-center justify-center gap-3">
            {isClockedIn ? (
                <>
                    <PlayCircle size={32} /> Clocked In
                </>
            ) : (
                <>
                    <StopCircle size={32} /> Off Duty
                </>
            )}
         </h2>

         {!isClockedIn ? (
             <Button 
                onClick={handleClockIn} 
                isLoading={isLoading} 
                variant="white"
                className="max-w-xs mx-auto"
             >
                {isLoading ? loadingText : 'Start Shift'}
             </Button>
         ) : (
             <Button 
                onClick={initiateClockOut} 
                variant="whiteDanger" 
                className="max-w-xs mx-auto"
             >
                End Shift
             </Button>
         )}
      </div>

      {/* Main Content Area */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">

        {/* Left Col: Procedures (Only visible when clocked in) */}
        {isClockedIn && (
            <div className="md:col-span-1">
                 <ProcedureTracker 
                    counts={currentProcedures} 
                    onChange={setCurrentProcedures} 
                    employeeCategory={employee.category}
                    procedures={procedures}
                 />
            </div>
        )}

        {/* Right Col: History */}
        <div className={`${isClockedIn ? 'md:col-span-2' : 'md:col-span-3'} space-y-4`}>
            <h2 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                Work History
            </h2>
            <div className="max-h-[600px] overflow-y-auto pr-2">
                <HistoryList 
                    history={data.history} 
                    procedures={procedures}
                    onRetrySync={handleRetrySync} 
                />
            </div>
        </div>
      </div>

      <ClockOutModal 
        isOpen={isClockOutModalOpen}
        onClose={() => setIsClockOutModalOpen(false)}
        onConfirm={confirmClockOut}
        procedures={currentProcedures}
        allProcedures={procedures}
        isProcessing={isLoading}
      />
    </div>
  );
};

import React from 'react';
import { ProcedureCounts, Procedure } from '../types';
import { Minus, Plus } from 'lucide-react';

interface ProcedureTrackerProps {
  counts: ProcedureCounts;
  onChange: (newCounts: ProcedureCounts) => void;
  employeeCategory: string;
  procedures: Record<string, Procedure>;
}

export const ProcedureTracker: React.FC<ProcedureTrackerProps> = ({ counts, onChange, employeeCategory, procedures }) => {

  const handleIncrement = (key: string) => {
    onChange({
      ...counts,
      [key]: (counts[key] || 0) + 1
    });
  };

  const handleDecrement = (key: string) => {
    if (!counts[key] || counts[key] <= 0) return;
    onChange({
      ...counts,
      [key]: counts[key] - 1
    });
  };

  // Filter procedures that match the employee's category
  const visibleProcedures = Object.entries(procedures).filter(
    ([_, proc]) => proc.category === employeeCategory
  );

  if (visibleProcedures.length === 0) {
    return (
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 text-center">
            <p className="text-gray-400 text-sm">No procedures available for your category ({employeeCategory}).</p>
        </div>
    );
  }

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
      <div className="bg-gray-50 px-5 py-4 border-b border-gray-100">
        <h3 className="text-base font-bold text-gray-800">Session Procedures</h3>
        <p className="text-xs text-gray-500 mt-0.5">Track items for bonus pay</p>
      </div>
      <div className="p-2 max-h-[400px] overflow-y-auto">
        {visibleProcedures.map(([key, proc]) => (
          <div key={key} className="flex justify-between items-center p-3 hover:bg-gray-50 rounded-lg transition-colors">
            <div className="flex flex-col">
              <span className="font-semibold text-gray-700 text-sm">{proc.name}</span>
              <span className="text-xs text-gray-400 font-medium tracking-wide">${proc.value.toFixed(2)}</span>
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={() => handleDecrement(key)}
                className="w-7 h-7 flex items-center justify-center rounded-full bg-gray-100 text-gray-600 hover:bg-gray-200 transition active:bg-gray-300"
                aria-label="Decrease count"
              >
                <Minus size={14} />
              </button>
              <div className="w-8 text-center font-bold text-sm text-indigo-900">
                {counts[key] || 0}
              </div>
              <button
                onClick={() => handleIncrement(key)}
                className="w-7 h-7 flex items-center justify-center rounded-full bg-indigo-50 text-indigo-600 hover:bg-indigo-100 transition active:bg-indigo-200"
                aria-label="Increase count"
              >
                <Plus size={14} />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

import React from 'react';
import { Session, Procedure } from '../types';
import { formatDate, formatTime, formatDuration, formatCurrency } from '../utils';
import { Clock, DollarSign, Calendar, CheckCircle, AlertCircle, RefreshCw } from 'lucide-react';

interface HistoryListProps {
  history: Session[];
  procedures: Record<string, Procedure>;
  onRetrySync: (session: Session) => void;
}

export const HistoryList: React.FC<HistoryListProps> = ({ history, procedures, onRetrySync }) => {
  if (history.length === 0) {
    return (
      <div className="text-center py-10 bg-white rounded-xl border border-dashed border-gray-300">
        <p className="text-gray-400">No work history found.</p>
      </div>
    );
  }

  // Sort by newest first
  const sortedHistory = [...history].sort((a, b) => 
    new Date(b.clockOut).getTime() - new Date(a.clockOut).getTime()
  );

  return (
    <div className="space-y-4">
      {sortedHistory.map((session) => {
        const duration = new Date(session.clockOut).getTime() - new Date(session.clockIn).getTime();
        const isFailed = session.syncStatus === 'failed';
        const isPending = session.syncStatus === 'pending';
        const isSynced = session.syncStatus === 'synced' || !session.syncStatus; // Backward compatibility

        return (
          <div key={session.id} className="bg-white border border-gray-200 rounded-xl p-5 shadow-sm hover:shadow-md transition-shadow">
            {/* Header */}
            <div className="flex justify-between items-start mb-4 border-b border-gray-100 pb-3">
              <div className="flex items-center gap-2 text-gray-800 font-bold">
                <Calendar size={18} className="text-indigo-500" />
                {formatDate(session.clockIn)}
              </div>
              <div className="flex items-center gap-2">
                <span className="px-3 py-1 bg-indigo-50 text-indigo-700 text-xs font-bold uppercase rounded-full tracking-wide">
                    {formatDuration(duration)}
                </span>
                {/* Sync Status Badge */}
                {isSynced && <CheckCircle size={18} className="text-green-500" title="Synced to Google Sheets" />}
                {isPending && <div className="animate-spin rounded-full h-4 w-4 border-2 border-indigo-500 border-t-transparent"></div>}
                {isFailed && (
                    <button 
                        onClick={() => onRetrySync(session)}
                        className="text-red-500 hover:text-red-700 hover:bg-red-50 p-1 rounded-full transition-colors"
                        title="Sync Failed. Tap to retry."
                    >
                        <RefreshCw size={18} />
                    </button>
                )}
              </div>
            </div>

            {/* Times & Location */}
            <div className="grid grid-cols-2 gap-4 text-sm mb-4">
              <div className="space-y-1">
                <p className="text-xs text-gray-500 uppercase tracking-wider font-semibold">Clock In</p>
                <div className="flex items-center gap-2">
                    <Clock size={14} className="text-green-600" />
                    <span className="font-medium">{formatTime(session.clockIn)}</span>
                </div>
              </div>

              <div className="space-y-1">
                <p className="text-xs text-gray-500 uppercase tracking-wider font-semibold">Clock Out</p>
                <div className="flex items-center gap-2">
                    <Clock size={14} className="text-red-500" />
                    <span className="font-medium">{formatTime(session.clockOut)}</span>
                </div>
              </div>
            </div>

            {/* Procedures & Earnings */}
            <div className="bg-gray-50 rounded-lg p-3">
                {Object.keys(session.procedures).length > 0 ? (
                   <div className="mb-3">
                       <p className="text-xs font-semibold text-gray-500 mb-2 uppercase">Procedures</p>
                       <ul className="grid grid-cols-2 gap-2">
                           {Object.entries(session.procedures).map(([key, count]) => (
                               <li key={key} className="flex justify-between text-xs bg-white px-2 py-1 rounded border border-gray-200">
                                   <span className="text-gray-600">{procedures[key]?.name || key}</span>
                                   <span className="font-bold text-gray-900">{count}</span>
                               </li>
                           ))}
                       </ul>
                   </div>
                ) : (
                    <p className="text-xs text-gray-400 italic mb-3">No procedures recorded.</p>
                )}

                <div className="border-t border-gray-200 pt-2 mt-2 flex justify-between items-center">
                    <span className="text-xs font-medium text-gray-600">Est. Total Pay</span>
                    <span className="text-sm font-bold text-green-600 flex items-center gap-1">
                        <DollarSign size={14} />
                        {formatCurrency(session.earnings?.total || 0)}
                    </span>
                </div>
            </div>

            {isFailed && (
                <div className="mt-3 bg-red-50 text-red-600 text-xs p-2 rounded flex items-center gap-2">
                    <AlertCircle size={14} />
                    <span>Sync failed. Check connection and tap retry icon.</span>
                </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

import React from 'react';
import { ProcedureCounts, Procedure } from '../types';
import { Button } from './ui/Button';
import { AlertTriangle, CheckCircle } from 'lucide-react';

interface ClockOutModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  procedures: ProcedureCounts;
  allProcedures: Record<string, Procedure>;
  isProcessing: boolean;
}

export const ClockOutModal: React.FC<ClockOutModalProps> = ({ 
  isOpen, 
  onClose, 
  onConfirm, 
  procedures,
  allProcedures,
  isProcessing
}) => {
  if (!isOpen) return null;

  const hasProcedures = Object.keys(procedures).some(key => procedures[key] > 0);

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto" aria-labelledby="modal-title" role="dialog" aria-modal="true">
